def group_anagrams(strs):
    groups = []                                             # list of (signature, list of strings) pairs
    for s in strs:
        signature = ''.join(sorted(s))
        placed = False
        for group in groups:                                    # scan every existing group for a match
            if group[0] == signature:
                group[1].append(s)
                placed = True
                break
        if not placed:
            groups.append([signature, [s]])                        # start a brand new group
    return [group[1] for group in groups]


if __name__ == "__main__":
    strs = ["eat", "tea", "tan", "ate", "nat", "bat"]
    print(group_anagrams(strs))

