import java.util.*;

public class Main {
    List<List<String>> groupAnagrams(String[] strs) {
        List<String> signatures = new ArrayList<>();
        List<List<String>> groups = new ArrayList<>();
        for (String s : strs) {
            char[] chars = s.toCharArray();
            Arrays.sort(chars);
            String signature = new String(chars);
            int foundIndex = -1;
            for (int i = 0; i < signatures.size(); i++) {               // scan every existing group for a match
                if (signatures.get(i).equals(signature)) { foundIndex = i; break; }
            }
            if (foundIndex != -1) {
                groups.get(foundIndex).add(s);
            } else {
                signatures.add(signature);
                List<String> newGroup = new ArrayList<>();
                newGroup.add(s);
                groups.add(newGroup);                                       // start a brand new group
            }
        }
        return groups;
    }

    public static void main(String[] args) {
        String[] strs = {"eat", "tea", "tan", "ate", "nat", "bat"};
        Main solution = new Main();
        System.out.println(solution.groupAnagrams(strs));
    }
}

