#include <bits/stdc++.h>
using namespace std;

vector<vector<string>> groupAnagrams(vector<string>& strs) {
    vector<string> signatures;
    vector<vector<string>> groups;
    for (string s : strs) {
        string signature = s;
        sort(signature.begin(), signature.end());
        int foundIndex = -1;
        for (int i = 0; i < (int)signatures.size(); i++) {            // scan every existing group for a match
            if (signatures[i] == signature) { foundIndex = i; break; }
        }
        if (foundIndex != -1) {
            groups[foundIndex].push_back(s);
        } else {
            signatures.push_back(signature);
            groups.push_back({s});                                        // start a brand new group
        }
    }
    return groups;
}

int main() {
    vector<string> strs = {"eat", "tea", "tan", "ate", "nat", "bat"};
    vector<vector<string>> result = groupAnagrams(strs);
    for (auto& group : result) {
        cout << "[";
        for (auto& s : group) cout << s << " ";
        cout << "] ";
    }
    cout << endl;
    return 0;
}

